version: '3.8'

services:
  pi-agent:
    build:
      context: .
      args:
        - USER_ID=${USER_ID:-1000}
        - GROUP_ID=${GROUP_ID:-1000}
    container_name: pi-coding-agent
    network_mode: host
    volumes:
      # Mount the project root (relative to this file) to /app
      - ..:/app
      # Persistent folder for agent configs, sessions, and auth
      - ./pi-config:/home/piuser/.pi/agent
    working_dir: /app
    stdin_open: true
    tty: true
    # Pass through API keys and pi settings from the .env file.
    # Copy .env.example to .env and fill in your key.
    environment:
      - ANTHROPIC_API_KEY=${ANTHROPIC_API_KEY:-}
      - ANTHROPIC_BASE_URL=${ANTHROPIC_BASE_URL:-}
      - OPENAI_API_KEY=${OPENAI_API_KEY:-}
      - OPENAI_BASE_URL=${OPENAI_BASE_URL:-}
      - GOOGLE_API_KEY=${GOOGLE_API_KEY:-}
      - DEEPSEEK_API_KEY=${DEEPSEEK_API_KEY:-}
      - GROQ_API_KEY=${GROQ_API_KEY:-}
      - MISTRAL_API_KEY=${MISTRAL_API_KEY:-}
      - XAI_API_KEY=${XAI_API_KEY:-}
      - CEREBRAS_API_KEY=${CEREBRAS_API_KEY:-}
      - OPENROUTER_API_KEY=${OPENROUTER_API_KEY:-}
      - TOGETHER_API_KEY=${TOGETHER_API_KEY:-}
      - FIREWORKS_API_KEY=${FIREWORKS_API_KEY:-}
      - HUGGINGFACE_API_KEY=${HUGGINGFACE_API_KEY:-}
      - OLLAMA_BASE_URL=${OLLAMA_BASE_URL:-http://localhost:11434}
      - OLLAMA_API_KEY=${OLLAMA_API_KEY:-}
      - PI_SKIP_VERSION_CHECK=${PI_SKIP_VERSION_CHECK:-}
      - PI_CODING_AGENT_DIR=/home/piuser/.pi/agent
